  items:=items||jsonb_build_array(q);
 end loop;
 d:=jsonb_build_object('title','Synthetic unanswered scoring','instructions','','mode','PLATFORM_QUESTIONS','published',true,'usesMarks',true,'filePoints',10,'questions',items,'modelAnswer','','solutionVideo','','solutionVideoId',null,'referenceIds','[]'::jsonb,'solutionIds','[]'::jsonb);
