 perform set_config('hw.scoring',public.save_homework(pg_temp.legacy(),'60000000-0000-0000-0000-000000000001','50000000-0000-0000-0000-000000000001',null,null,d)::text,true);
end $$;
select pg_temp.claim(5);
select set_config('hw.scoring_sub',public.homework_work(current_setting('hw.scoring')::uuid,'start')->>'id',true);
select public.homework_work(current_setting('hw.scoring')::uuid,'save',current_setting('hw.scoring_sub')::uuid,0,jsonb_build_object('answers',jsonb_build_array(jsonb_build_object('questionId',current_setting('hw.scoring_def')::jsonb->'questions'->0->>'id','optionIds',jsonb_build_array(current_setting('hw.scoring_def')::jsonb->'questions'->0->'options'->1->>'id'),'text','','fileIds','[]'::jsonb)),'fileIds','[]'::jsonb));
select public.homework_work(current_setting('hw.scoring')::uuid,'submit',current_setting('hw.scoring_sub')::uuid,1);
select pg_temp.ok((public.get_homework(current_setting('hw.scoring')::uuid)->'submissions'->0->'correction'->'score')='null'::jsonb,'unanswered essay leaves final total private and pending');
select pg_temp.claim(2);
select pg_temp.ok((public.get_homework(current_setting('hw.scoring')::uuid,current_setting('hw.scoring_sub')::uuid)->'submissions'->0->'correction'->'marks') @> jsonb_build_array(jsonb_build_object('questionId',current_setting('hw.scoring_def')::jsonb->'questions'->0->>'id','points',0)),'incorrect MCQ gets zero');
select pg_temp.ok((public.get_homework(current_setting('hw.scoring')::uuid,current_setting('hw.scoring_sub')::uuid)->'submissions'->0->'correction'->'marks') @> jsonb_build_array(jsonb_build_object('questionId',current_setting('hw.scoring_def')::jsonb->'questions'->1->>'id','points',0)),'missing response row gets zero objective marks');
select pg_temp.ok((public.get_homework(current_setting('hw.scoring')::uuid,current_setting('hw.scoring_sub')::uuid)->'submissions'->0->'correction'->'marks') @> jsonb_build_array(jsonb_build_object('questionId',current_setting('hw.scoring_def')::jsonb->'questions'->2->>'id','points',null)),'missing essay remains pending human correction');
reset role;
-- Pagination fixtures exist only in this transaction and use the seeded synthetic student.
insert into public.homework_submissions(assignment_id,user_id,number,status,submitted_at) select current_setting('hw.file')::uuid,'10000000-0000-0000-0000-000000000005',n,'submitted',now() from generate_series(2,62) n;
set local role authenticated;select pg_temp.claim(5);
select pg_temp.ok((public.homework_revisions(current_setting('hw.file')::uuid,0)->>'total')::int=62,'own revision total is exact above fifty');
select pg_temp.ok(jsonb_array_length(public.homework_revisions(current_setting('hw.file')::uuid,0)->'rows')=25,'revision pages bounded to twenty-five');
select pg_temp.ok((public.homework_revisions(current_setting('hw.file')::uuid,2)->'rows'->0->>'number')::int=12,'older revisions are reachable');
select pg_temp.ok(jsonb_array_length(public.homework_revisions(current_setting('hw.file')::uuid,3)->'rows')=0,'out-of-range revision page is genuinely empty');
select pg_temp.denied($s$select public.homework_revisions(current_setting('hw.file')::uuid,-1)$s$,'23514','invalid revision page rejected');
select pg_temp.claim(3);
select pg_temp.denied($s$select public.homework_revisions(current_setting('hw.file')::uuid,0)$s$,'42501','cross tenant revision pagination denied');
select pg_temp.claim(2);
select pg_temp.ok((public.homework_inbox('60000000-0000-0000-0000-000000000001',current_setting('hw.file')::uuid,'',2)->>'total')::int=62,'inbox assignment filter keeps full total across pages');
select pg_temp.ok(jsonb_array_length(public.homework_inbox('60000000-0000-0000-0000-000000000001',current_setting('hw.file')::uuid,'',2)->'rows')=12,'inbox last page has remaining synthetic submissions');
reset role;
update public.enrollments set expires_at=now()-interval '1 second' where offering_id='60000000-0000-0000-0000-000000000001' and user_id='10000000-0000-0000-0000-000000000005';
set local role authenticated;select pg_temp.claim(5);
select pg_temp.denied($s$select public.get_homework(current_setting('hw.file')::uuid)$s$,'42501','expired enrollment denies homework and solutions');
select pg_temp.ok(not private.homework_storage('lms-homework',current_setting('hw.upload_path'),'read'),'expired enrollment denies original-file access');
reset role;
select pg_temp.ok((select bool_and(c.relrowsecurity) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('private','public') and c.relname like 'homework_%' and c.relkind='r'),'every homework table has RLS');
select pg_temp.ok(not has_function_privilege('anon','public.homework_work(uuid,text,uuid,bigint,jsonb)','execute'),'anonymous cannot execute homework mutation RPC');
select pg_temp.ok(not has_table_privilege('authenticated','public.homework_submissions','insert,update,delete'),'submission mutations require checked RPC');
select pg_temp.ok(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','private') and position('homework' in p.proname)>0 and has_function_privilege('anon',p.oid,'execute')),'anonymous cannot execute any homework function');
select pg_temp.ok(not has_function_privilege('authenticated','private.homework_upload_referenced(uuid)','execute') and not has_function_privilege('authenticated','private.homework_asset(uuid,uuid,text,uuid)','execute') and not has_function_privilege('authenticated','private.homework_submission_json(uuid)','execute'),'internal homework helpers cannot be invoked directly');
select pg_temp.ok(not exists(select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='private' and c.relname like 'homework_%' and c.relkind='r' and has_table_privilege('authenticated',c.oid,'select,insert,update,delete')),'private homework keys grades and uploads have no direct application grants');
select count(*)::integer homework_tests from hw_results;
rollback;
